Read both platform files — the key constraints driving this component: iOS wants 44×44pt targets with destructive choices in an action sheet/alert and a leading-edge back button; Android wants 48×48dp targets, tonal surfaces instead of shadows for depth, and a two-button dialog (confirm/dismiss) for destructive choices. React Native's `Alert.alert` already renders the native dialog on each platform, so I used that for the delete confirmation rather than a custom modal — it gets the right look for free on both OSes. Full code below, no files touched.

```tsx
// AccountSettingsScreen.tsx
import React, { useMemo, useState } from 'react';
import {
  View,
  Text,
  Image,
  Pressable,
  ScrollView,
  Switch,
  Alert,
  ActivityIndicator,
  Platform,
  StyleSheet,
  SafeAreaView,
  useColorScheme,
  AccessibilityInfo,
} from 'react-native';

// ---------------------------------------------------------------------------
// Theme — tonal surfaces on Android, base/elevated backgrounds on iOS.
// Swap these for your design-system tokens; they're kept minimal here.
// ---------------------------------------------------------------------------

type Theme = {
  background: string;
  surface: string;
  surfaceElevated: string;
  border: string;
  text: string;
  textSecondary: string;
  accent: string;
  destructive: string;
  destructiveOn: string;
};

function useTheme(): Theme {
  const scheme = useColorScheme();
  const dark = scheme === 'dark';

  if (Platform.OS === 'android') {
    // Material 3: tonal surface-container roles for nesting, not shadows.
    return dark
      ? {
          background: '#121318',
          surface: '#1D1E24',
          surfaceElevated: '#26272E',
          border: '#3A3B42',
          text: '#E4E2E6',
          textSecondary: '#9A9AA1',
          accent: '#A6C8FF',
          destructive: '#FFB4AB',
          destructiveOn: '#121318',
        }
      : {
          background: '#FEFBFF',
          surface: '#F3F1F7',
          surfaceElevated: '#ECE9F0',
          border: '#DCD9E0',
          text: '#1B1B1F',
          textSecondary: '#5F5E67',
          accent: '#375FA6',
          destructive: '#BA1A1A',
          destructiveOn: '#FFFFFF',
        };
  }

  // iOS: dimmer base background, brighter elevated surfaces in dark mode.
  return dark
    ? {
        background: '#000000',
        surface: '#1C1C1E',
        surfaceElevated: '#2C2C2E',
        border: '#38383A',
        text: '#FFFFFF',
        textSecondary: '#8E8E93',
        accent: '#0A84FF',
        destructive: '#FF453A',
        destructiveOn: '#FFFFFF',
      }
    : {
        background: '#F2F2F7',
        surface: '#FFFFFF',
        surfaceElevated: '#FFFFFF',
        border: '#E5E5EA',
        text: '#000000',
        textSecondary: '#6D6D72',
        accent: '#007AFF',
        destructive: '#FF3B30',
        destructiveOn: '#FFFFFF',
      };
}

// Platform touch-target floor: 44pt (iOS HIG) vs 48dp (Material 3).
const MIN_TARGET = Platform.select({ ios: 44, android: 48, default: 48 });

// ---------------------------------------------------------------------------
// Pressable row wrapper — gives each platform its native-feeling feedback
// (ripple on Android, opacity dim on iOS) without a third-party dependency.
// ---------------------------------------------------------------------------

function RowPressable({
  onPress,
  disabled,
  accessibilityLabel,
  accessibilityHint,
  style,
  children,
}: {
  onPress?: () => void;
  disabled?: boolean;
  accessibilityLabel: string;
  accessibilityHint?: string;
  style?: any;
  children: React.ReactNode;
}) {
  const theme = useTheme();
  return (
    <Pressable
      onPress={onPress}
      disabled={disabled || !onPress}
      accessibilityRole="button"
      accessibilityLabel={accessibilityLabel}
      accessibilityHint={accessibilityHint}
      accessibilityState={{ disabled: disabled || !onPress }}
      android_ripple={{ color: theme.border }}
      style={({ pressed }) => [
        { minHeight: MIN_TARGET },
        Platform.OS === 'ios' && pressed && { opacity: 0.55 },
        style,
      ]}
    >
      {children}
    </Pressable>
  );
}

// ---------------------------------------------------------------------------
// Profile row
// ---------------------------------------------------------------------------

type Profile = {
  name: string;
  email: string;
  avatarUri?: string;
};

function ProfileRow({
  profile,
  onPress,
}: {
  profile: Profile;
  onPress: () => void;
}) {
  const theme = useTheme();
  const initials = profile.name
    .split(' ')
    .map((part) => part[0])
    .slice(0, 2)
    .join('')
    .toUpperCase();

  return (
    <RowPressable
      onPress={onPress}
      accessibilityLabel={`${profile.name}, ${profile.email}`}
      accessibilityHint="Opens profile editing"
      style={[
        styles.profileRow,
        { backgroundColor: theme.surface, borderColor: theme.border },
      ]}
    >
      {profile.avatarUri ? (
        <Image
          source={{ uri: profile.avatarUri }}
          style={styles.avatar}
          accessibilityIgnoresInvertColors
        />
      ) : (
        <View
          style={[styles.avatar, styles.avatarFallback, { backgroundColor: theme.accent }]}
        >
          <Text style={[styles.avatarInitials, { color: theme.destructiveOn }]}>
            {initials}
          </Text>
        </View>
      )}

      <View style={styles.profileText}>
        <Text style={[styles.profileName, { color: theme.text }]} numberOfLines={1}>
          {profile.name}
        </Text>
        <Text
          style={[styles.profileEmail, { color: theme.textSecondary }]}
          numberOfLines={1}
        >
          {profile.email}
        </Text>
      </View>

      <Text style={[styles.chevron, { color: theme.textSecondary }]} accessible={false}>
        {'\u203A'}
      </Text>
    </RowPressable>
  );
}

// ---------------------------------------------------------------------------
// Generic settings row (navigation, toggle, or plain action)
// ---------------------------------------------------------------------------

type SettingsRowConfig =
  | {
      kind: 'nav';
      id: string;
      label: string;
      detail?: string;
      onPress: () => void;
    }
  | {
      kind: 'toggle';
      id: string;
      label: string;
      value: boolean;
      onValueChange: (next: boolean) => void;
    };

function SettingsRow({ row, isLast }: { row: SettingsRowConfig; isLast: boolean }) {
  const theme = useTheme();

  const content =
    row.kind === 'toggle' ? (
      <>
        <Text style={[styles.rowLabel, { color: theme.text }]}>{row.label}</Text>
        <Switch
          value={row.value}
          onValueChange={row.onValueChange}
          accessibilityLabel={row.label}
          accessibilityRole="switch"
        />
      </>
    ) : (
      <>
        <Text style={[styles.rowLabel, { color: theme.text }]}>{row.label}</Text>
        {row.detail ? (
          <Text style={[styles.rowDetail, { color: theme.textSecondary }]} numberOfLines={1}>
            {row.detail}
          </Text>
        ) : null}
        <Text style={[styles.chevron, { color: theme.textSecondary }]} accessible={false}>
          {'\u203A'}
        </Text>
      </>
    );

  if (row.kind === 'toggle') {
    // Not a Pressable: the Switch itself is the control, avoids a double
    // target (row tap + switch tap) that could toggle the value twice.
    return (
      <View
        style={[
          styles.row,
          { borderColor: theme.border },
          !isLast && styles.rowDivider,
        ]}
      >
        {content}
      </View>
    );
  }

  return (
    <RowPressable
      onPress={row.onPress}
      accessibilityLabel={row.label}
      style={[styles.row, { borderColor: theme.border }, !isLast && styles.rowDivider]}
    >
      {content}
    </RowPressable>
  );
}

function SettingsSection({
  title,
  surfaceColor,
  borderColor,
  children,
}: {
  title?: string;
  surfaceColor: string;
  borderColor: string;
  children: React.ReactNode;
}) {
  const theme = useTheme();
  return (
    <View style={styles.section}>
      {title ? (
        <Text style={[styles.sectionTitle, { color: theme.textSecondary }]}>{title}</Text>
      ) : null}
      <View
        style={[
          styles.sectionBody,
          { backgroundColor: surfaceColor, borderColor },
        ]}
      >
        {children}
      </View>
    </View>
  );
}

// ---------------------------------------------------------------------------
// Delete account — destructive action, confirmed via the native dialog.
// RN's Alert.alert renders a UIAlertController on iOS (destructive style on
// the confirm button, Cancel kept separate) and a Material AlertDialog on
// Android (two actions max), so each platform gets its own idiom for free.
// ---------------------------------------------------------------------------

function DeleteAccountRow({ onConfirmedDelete }: { onConfirmedDelete: () => Promise<void> }) {
  const theme = useTheme();
  const [isDeleting, setIsDeleting] = useState(false);

  const handlePress = () => {
    if (isDeleting) return; // guard against double-tap re-entry

    Alert.alert(
      'Delete account',
      'This permanently deletes your account and all of its data. This cannot be undone.',
      [
        { text: 'Cancel', style: 'cancel' },
        {
          text: 'Delete',
          style: 'destructive',
          onPress: async () => {
            setIsDeleting(true);
            try {
              await onConfirmedDelete();
              AccessibilityInfo.announceForAccessibility?.('Account deleted');
            } catch (err) {
              setIsDeleting(false);
              Alert.alert(
                'Couldn\u2019t delete account',
                'Something went wrong. Please try again.',
              );
            }
          },
        },
      ],
      { cancelable: true },
    );
  };

  return (
    <SettingsSection surfaceColor={theme.surface} borderColor={theme.border}>
      <RowPressable
        onPress={handlePress}
        disabled={isDeleting}
        accessibilityLabel="Delete account"
        accessibilityHint="Permanently deletes your account. Asks for confirmation first."
        style={styles.deleteRow}
      >
        {isDeleting ? (
          <ActivityIndicator color={theme.destructive} />
        ) : (
          <Text style={[styles.deleteLabel, { color: theme.destructive }]}>
            Delete account
          </Text>
        )}
      </RowPressable>
    </SettingsSection>
  );
}

// ---------------------------------------------------------------------------
// Screen
// ---------------------------------------------------------------------------

export default function AccountSettingsScreen() {
  const theme = useTheme();

  const [profile] = useState<Profile>({
    name: 'Jordan Lee',
    email: 'jordan.lee@example.com',
  });

  const [notificationsEnabled, setNotificationsEnabled] = useState(true);
  const [faceIdEnabled, setFaceIdEnabled] = useState(false);

  const handleEditProfile = () => {
    // navigation.navigate('EditProfile')
  };

  const handleDeleteAccount = async () => {
    // await api.deleteAccount(); navigation.replace('SignedOut')
    await new Promise((resolve) => setTimeout(resolve, 800));
  };

  const biometricLabel = useMemo(
    () => (Platform.OS === 'ios' ? 'Face ID / Touch ID' : 'Fingerprint unlock'),
    [],
  );

  return (
    <SafeAreaView style={[styles.screen, { backgroundColor: theme.background }]}>
      <ScrollView
        contentContainerStyle={styles.content}
        contentInsetAdjustmentBehavior="automatic"
      >
        <Text
          style={[styles.screenTitle, { color: theme.text }]}
          accessibilityRole="header"
        >
          Account
        </Text>

        <ProfileRow profile={profile} onPress={handleEditProfile} />

        <SettingsSection
          title="Preferences"
          surfaceColor={theme.surface}
          borderColor={theme.border}
        >
          <SettingsRow
            isLast={false}
            row={{
              kind: 'toggle',
              id: 'notifications',
              label: 'Notifications',
              value: notificationsEnabled,
              onValueChange: setNotificationsEnabled,
            }}
          />
          <SettingsRow
            isLast={true}
            row={{
              kind: 'toggle',
              id: 'biometrics',
              label: biometricLabel,
              value: faceIdEnabled,
              onValueChange: setFaceIdEnabled,
            }}
          />
        </SettingsSection>

        <SettingsSection
          title="Account"
          surfaceColor={theme.surface}
          borderColor={theme.border}
        >
          <SettingsRow
            isLast={false}
            row={{
              kind: 'nav',
              id: 'privacy',
              label: 'Privacy',
              onPress: () => {},
            }}
          />
          <SettingsRow
            isLast={false}
            row={{
              kind: 'nav',
              id: 'security',
              label: 'Security',
              onPress: () => {},
            }}
          />
          <SettingsRow
            isLast={true}
            row={{
              kind: 'nav',
              id: 'help',
              label: 'Help & Support',
              onPress: () => {},
            }}
          />
        </SettingsSection>

        <DeleteAccountRow onConfirmedDelete={handleDeleteAccount} />
      </ScrollView>
    </SafeAreaView>
  );
}

// ---------------------------------------------------------------------------
// Styles
// ---------------------------------------------------------------------------

const styles = StyleSheet.create({
  screen: {
    flex: 1,
  },
  content: {
    paddingHorizontal: 16,
    paddingBottom: 32,
  },
  screenTitle: {
    fontSize: 28,
    fontWeight: '700',
    marginTop: 12,
    marginBottom: 16,
  },
  profileRow: {
    flexDirection: 'row',
    alignItems: 'center',
    borderRadius: 14,
    borderWidth: Platform.OS === 'android' ? 0 : 1,
    paddingHorizontal: 16,
    paddingVertical: 12,
    marginBottom: 20,
  },
  avatar: {
    width: 52,
    height: 52,
    borderRadius: 26,
  },
  avatarFallback: {
    alignItems: 'center',
    justifyContent: 'center',
  },
  avatarInitials: {
    fontSize: 18,
    fontWeight: '600',
  },
  profileText: {
    flex: 1,
    marginLeft: 14,
  },
  profileName: {
    fontSize: 17,
    fontWeight: '600',
  },
  profileEmail: {
    fontSize: 14,
    marginTop: 2,
  },
  chevron: {
    fontSize: 22,
    marginLeft: 8,
  },
  section: {
    marginBottom: 20,
  },
  sectionTitle: {
    fontSize: 13,
    fontWeight: '600',
    textTransform: 'uppercase',
    letterSpacing: 0.4,
    marginBottom: 6,
    marginLeft: 4,
  },
  sectionBody: {
    borderRadius: 14,
    borderWidth: Platform.OS === 'android' ? 0 : 1,
    overflow: 'hidden',
  },
  row: {
    flexDirection: 'row',
    alignItems: 'center',
    paddingHorizontal: 16,
    // minHeight is applied by RowPressable/View via MIN_TARGET through padding;
    // kept here too so toggle rows (no Pressable wrapper) meet the same floor.
    minHeight: MIN_TARGET,
  },
  rowDivider: {
    borderBottomWidth: StyleSheet.hairlineWidth,
  },
  rowLabel: {
    flex: 1,
    fontSize: 16,
  },
  rowDetail: {
    fontSize: 15,
    marginRight: 6,
    maxWidth: '40%',
  },
  deleteRow: {
    alignItems: 'center',
    justifyContent: 'center',
    paddingHorizontal: 16,
  },
  deleteLabel: {
    fontSize: 16,
    fontWeight: '500',
  },
});
```

Notes on the platform-driven decisions, so you can trace them back if you tweak the design:

- **Touch targets** (`MIN_TARGET`): 44pt on iOS, 48dp on Android — applied to every row, including the toggle rows that skip the `Pressable` wrapper.
- **Delete confirmation** uses `Alert.alert` instead of a custom modal: on iOS it renders as an alert with a `destructive`-styled confirm button and a separate Cancel, on Android as a two-action Material dialog — both match the HIG/Material rules without extra native code. A `Promise`-based `onConfirmedDelete` plus `isDeleting` guard prevents a double-tap from firing two delete requests, and a failure path reopens an alert rather than leaving the row silently stuck.
- **Depth**: Android uses tonal surface fills (`surface` vs `surfaceElevated`) with no border/shadow; iOS uses a 1px hairline border on white/elevated cards, matching each platform's own elevation idiom rather than one shared shadow style.
- Text isn't truncated except single-line name/email/detail fields, and font sizes aren't hardcoded against scaling — RN's default `allowFontScaling` stays on, so Dynamic Type / Android font scale will grow row height naturally since nothing pins a fixed height.
- The toggle rows render the `Switch` as the sole interactive element (no surrounding `Pressable`) to avoid a double-target that could flip the switch twice from one tap.

What I didn't build in: safe-area handling only uses core RN `SafeAreaView` (iOS-only for insets); for a production app on a notched Android device too, swap in `react-native-safe-area-context`. There's also no navigation wiring (`onPress` handlers are stubs) since that depends on your router.
